"""Phase 3 form showcase pages. Keep page content separate from the shared shell."""

FORM_PAGES = (
    'basic-form', 'forms-advanced-form', 'forms-editor',
    'forms-validation', 'form-wizard',
)


def build_form_pages(heading, card):
    overview_items = [
        ('basic-form', 'Form dasar', 'Input, pilihan, upload lokal, dan validasi Bootstrap.', 'bg-yellow'),
        ('forms-advanced-form', 'Advanced form', 'Layout dua kolom, helper, tooltip, dan Select2.', 'bg-purple'),
        ('forms-editor', 'Rich text editor', 'Editor Quill dengan toolbar lengkap dan dua tema.', 'bg-green'),
        ('forms-validation', 'Validasi form', 'Aturan HTML5 dan pesan error per field.', 'bg-orange'),
        ('form-wizard', 'Form wizard', 'Empat langkah dengan pemeriksaan sebelum lanjut.', 'bg-blue'),
    ]
    overview = heading('Form untuk setiap alur.', 'Mulai dari input sederhana hingga wizard bertahap. Pilih contoh yang ingin kamu eksplorasi.')
    overview += '<div class="row g-4">' + ''.join(
        f'<div class="col-md-6 col-xl-4"><a class="card form-index-card h-100 text-decoration-none text-dark" href="{slug}.html"><div class="card-body"><span class="badge {color} mb-3">{name}</span><h2 class="fs-4">{name} →</h2><p class="mb-0 text-muted">{description}</p></div></a></div>'
        for slug, name, description, color in overview_items
    ) + '</div>'

    advanced = heading('Form yang lebih cerdas.', 'Field yang tersusun rapi dan pilihan yang mudah dicari.')
    advanced += '''<div class="row g-4"><div class="col-xl-8"><section class="card"><div class="card-body"><h2>Brief proyek</h2><p class="text-muted small">Isi data contoh lalu lihat ringkasannya. Tidak ada data dikirim.</p><form id="advancedForm" novalidate><fieldset class="mb-4"><legend class="fs-5 fw-bold mb-3">Identitas proyek</legend><div class="row g-3"><div class="col-md-6"><label class="form-label" for="advancedName">Nama proyek <span class="text-danger">*</span></label><input class="form-control" id="advancedName" name="name" required maxlength="70" placeholder="Website studio"><div class="invalid-feedback">Isi nama proyek.</div></div><div class="col-md-6"><label class="form-label" for="advancedEmail">Email kontak <span class="text-danger">*</span></label><input class="form-control" id="advancedEmail" name="email" type="email" required placeholder="halo@studio.id"><div class="invalid-feedback">Masukkan email yang valid.</div></div><div class="col-md-6"><label class="form-label" for="advancedTeam">Tim penanggung jawab <span class="text-danger">*</span></label><select class="form-select" id="advancedTeam" name="team" required><option value=""></option><option>Studio Desain</option><option>Tim Produk</option><option>Tim Engineering</option><option>Tim Pemasaran</option></select><div class="form-text">Ketik nama tim untuk mencari pilihan.</div><p class="small text-danger mb-0 d-none" id="advancedTeamError">Pilih tim penanggung jawab.</p></div><div class="col-md-6"><label class="form-label" for="advancedSkills">Keahlian yang dibutuhkan</label><select class="form-select" id="advancedSkills" name="skills" multiple><option>Desain UI</option><option>Riset pengguna</option><option>Frontend</option><option>Backend</option><option>Copywriting</option></select><div class="form-text">Boleh pilih lebih dari satu.</div></div></div></fieldset><fieldset class="mb-4"><legend class="fs-5 fw-bold mb-3">Ruang lingkup</legend><div class="row g-3"><div class="col-md-6"><label class="form-label" for="advancedDate">Target mulai</label><input class="form-control" id="advancedDate" name="date" type="date"></div><div class="col-md-6"><label class="form-label" for="advancedBudget">Perkiraan budget</label><div class="input-group"><span class="input-group-text">Rp</span><input class="form-control" id="advancedBudget" name="budget" type="number" min="1" step="1" placeholder="5000000"><button class="btn" type="button" data-bs-toggle="tooltip" title="Masukkan angka rupiah tanpa titik atau koma." aria-label="Petunjuk budget">?</button></div><div class="form-text">Angka hanya untuk demo, tanpa transaksi.</div></div><div class="col-12"><label class="form-label" for="advancedNotes">Catatan singkat</label><textarea class="form-control" id="advancedNotes" name="notes" rows="4" maxlength="400" placeholder="Ceritakan hasil yang kamu harapkan..."></textarea><div class="form-text">Maksimal 400 karakter.</div></div></div></fieldset><div class="d-flex flex-wrap gap-2"><button class="btn btn-primary" type="submit">Lihat ringkasan</button><button class="btn" type="reset">Reset</button></div><p id="advancedResult" class="small mt-3 mb-0" role="status"></p></form></div></section></div><div class="col-xl-4"><section class="card bg-yellow"><div class="card-body"><span class="badge bg-white text-dark mb-3">SELECT2</span><h2>Lebih cepat memilih.</h2><p class="mb-0">Cari tim dengan mengetik. Tambahkan beberapa keahlian tanpa memenuhi layar dengan daftar panjang.</p></div></section></div></div>'''

    editor = heading('Tulis ide lebih leluasa.', 'Quill memberi format teks langsung di browser, tanpa penyimpanan server.')
    editor += '''<div class="row g-4"><div class="col-xl-8"><section class="card"><div class="card-body"><h2>Editor utama · Snow</h2><p class="small text-muted">Gunakan judul, bold, italic, daftar, tautan, gambar, dan blok kode pada toolbar.</p><div id="editorSnow"><h2>Ide berikutnya dimulai di sini</h2><p>Tulis sebuah cerita, susun poin, dan buat kontenmu terasa hidup.</p></div><div class="d-flex flex-wrap gap-2 mt-3"><button class="btn btn-primary" id="editorPreview" type="button">Lihat hasil</button><button class="btn" id="editorClear" type="button">Kosongkan</button></div><p id="editorStatus" class="small mt-3 mb-0" role="status"></p></div></section><section class="card mt-4"><div class="card-body"><h2>Preview teks</h2><pre id="editorOutput" class="code form-editor-output mb-0">Klik “Lihat hasil” untuk menampilkan teks editor.</pre></div></section></div><div class="col-xl-4"><section class="card"><div class="card-body"><h2>Editor pilihan · Bubble</h2><p class="small text-muted">Sorot teks untuk membuka toolbar ringkas.</p><div id="editorBubble"><p>Seleksi bagian kalimat ini lalu ubah tampilannya.</p></div></div></section><div class="alert alert-info small mt-4">Gambar yang dipilih berada sementara di browser. Demo ini tidak mengunggah atau menyimpan konten.</div></div></div>'''

    validation = heading('Pesan yang membantu.', 'Validasi HTML5 native dengan umpan balik Bootstrap pada setiap kolom.')
    validation += '''<div class="row g-4"><div class="col-xl-8"><section class="card"><div class="card-body"><h2>Daftar kampanye demo</h2><p class="text-muted small">Coba kirim kosong atau gunakan kode selain format ABC-123.</p><form id="validationForm" novalidate><div class="row g-3"><div class="col-md-6"><label class="form-label" for="validationName">Nama lengkap</label><input class="form-control" id="validationName" name="name" required minlength="3" maxlength="70" autocomplete="name"><div class="valid-feedback">Nama siap digunakan.</div><div class="invalid-feedback">Isi nama minimal 3 karakter.</div></div><div class="col-md-6"><label class="form-label" for="validationEmail">Email</label><input class="form-control" id="validationEmail" name="email" type="email" required autocomplete="email"><div class="valid-feedback">Email valid.</div><div class="invalid-feedback">Isi alamat email yang valid.</div></div><div class="col-md-6"><label class="form-label" for="validationCode">Kode kampanye</label><input class="form-control" id="validationCode" name="code" required pattern="[A-Z]{3}-[0-9]{3}" placeholder="ABC-123" aria-describedby="validationCodeHelp"><div class="form-text" id="validationCodeHelp">Tiga huruf kapital, tanda hubung, tiga angka.</div><div class="valid-feedback">Format kode benar.</div><div class="invalid-feedback">Gunakan format ABC-123.</div></div><div class="col-md-6"><label class="form-label" for="validationBudget">Jumlah peserta</label><input class="form-control" id="validationBudget" name="participants" type="number" required min="1" max="50" step="1" placeholder="1–50"><div class="valid-feedback">Jumlah sesuai.</div><div class="invalid-feedback">Masukkan bilangan bulat antara 1 dan 50.</div></div><div class="col-12"><div class="form-check"><input class="form-check-input" id="validationAgree" name="agree" type="checkbox" required><label class="form-check-label" for="validationAgree">Saya memahami ini hanya demonstrasi.</label><div class="invalid-feedback">Centang persetujuan untuk melanjutkan.</div></div></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary" type="submit">Periksa data</button><button class="btn" type="reset">Reset</button></div><p id="validationResult" class="small mt-3 mb-0" role="status"></p></form></div></section></div><div class="col-xl-4"><section class="card bg-green"><div class="card-body"><h2>Aturan jelas.</h2><p class="mb-0">Kolom wajib, pola kode, dan rentang angka diperiksa oleh browser. Warna dan teks Bootstrap menunjukkan apa yang perlu diperbaiki.</p></div></section></div></div>'''

    wizard = heading('Satu langkah setiap waktu.', 'Isi data diri, tentukan akun demo, lalu tinjau sebelum selesai.')
    wizard += '''<div class="row g-4"><div class="col-xl-9"><section class="card"><div class="card-body"><h2>Mulai registrasi demo</h2><p class="small text-muted">Data hanya digunakan untuk ringkasan di halaman ini.</p><div id="formWizard" class="form-wizard"><h3>Personal Info</h3><section><h4>Siapa kamu?</h4><div class="row g-3"><div class="col-md-6"><label class="form-label" for="wizardName">Nama lengkap</label><input class="form-control" id="wizardName" required minlength="3" autocomplete="name"><div class="invalid-feedback">Isi nama minimal 3 karakter.</div></div><div class="col-md-6"><label class="form-label" for="wizardPhone">Nomor telepon</label><input class="form-control" id="wizardPhone" type="tel" required pattern="[0-9+ ]{8,18}" placeholder="+62 812 3456 7890" autocomplete="tel"><div class="invalid-feedback">Isi 8–18 karakter angka, spasi, atau +.</div></div></div></section><h3>Account</h3><section><h4>Akun demo</h4><div class="row g-3"><div class="col-md-6"><label class="form-label" for="wizardEmail">Email akun</label><input class="form-control" id="wizardEmail" type="email" required autocomplete="email"><div class="invalid-feedback">Masukkan email yang valid.</div></div><div class="col-md-6"><label class="form-label" for="wizardRole">Peran</label><select class="form-select" id="wizardRole" required><option value="">Pilih peran…</option><option>Designer</option><option>Developer</option><option>Project manager</option></select><div class="invalid-feedback">Pilih peran.</div></div></div></section><h3>Confirmation</h3><section><h4>Periksa kembali</h4><dl class="row form-review"><dt class="col-sm-4">Nama</dt><dd class="col-sm-8" id="reviewName">—</dd><dt class="col-sm-4">Telepon</dt><dd class="col-sm-8" id="reviewPhone">—</dd><dt class="col-sm-4">Email</dt><dd class="col-sm-8" id="reviewEmail">—</dd><dt class="col-sm-4">Peran</dt><dd class="col-sm-8" id="reviewRole">—</dd></dl><div class="form-check"><input class="form-check-input" id="wizardAgree" type="checkbox" required><label class="form-check-label" for="wizardAgree">Data contoh di atas sudah benar.</label><div class="invalid-feedback">Centang konfirmasi sebelum lanjut.</div></div></section><h3>Done</h3><section><div class="text-center py-4"><span class="badge bg-green mb-3">SELESAI</span><h4>Semua langkah terisi!</h4><p class="mb-0">Ini hanya demo; tidak ada akun dibuat atau data dikirim.</p><button class="btn mt-4" id="wizardRestart" type="button">Ulangi demo</button></div></section></div><p id="wizardStatus" class="small mt-3 mb-0" role="status"></p></div></section></div><div class="col-xl-3"><div class="alert alert-warning small">Tombol lanjut memeriksa kolom pada langkah aktif sebelum membuka langkah berikutnya.</div></div></div>'''

    return {
        'forms': overview,
        'forms-advanced-form': advanced,
        'forms-editor': editor,
        'forms-validation': validation,
        'form-wizard': wizard,
    }
